test("partial overlap of 09:00 to 11:00 and 10:30 to 12:00 is 30 minutes", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  assert.equal(actual.minutes, 30);
});

test("09:00 to 11:00 and 10:30 to 12:00 count as overlapping because the overlap is greater than 0", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  assert.equal(actual.overlaps, true);
  assert.equal(actual.minutes, 30);
  assert.ok(actual.minutes > 0);
});

test("windows that only touch at 12:00 do not overlap and return 0 minutes", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "12:00", end: "13:00" });
  assert.equal(actual.overlaps, false);
  assert.equal(actual.minutes, 0);
});

test("giving 10:30 to 12:00 first still overlaps by 30 minutes the same as the other order", function () {
  var forward = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  var actual = code.windowOverlap({ start: "10:30", end: "12:00" }, { start: "09:00", end: "11:00" });
  assert.equal(actual.minutes, 30);
  assert.equal(actual.overlaps, true);
  assert.deepEqual(actual, forward);
});

test("giving 12:00 to 13:00 first still does not overlap and returns 0 the same as the other order", function () {
  var forward = code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "12:00", end: "13:00" });
  var actual = code.windowOverlap({ start: "12:00", end: "13:00" }, { start: "09:00", end: "12:00" });
  assert.equal(actual.minutes, 0);
  assert.equal(actual.overlaps, false);
  assert.deepEqual(actual, forward);
});

test("09:00 to 11:00 and 12:00 to 13:00 have a gap and overlap by 0 minutes", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "12:00", end: "13:00" });
  assert.equal(actual.minutes, 0);
});

test("same day windows with start and end in HH:mm are accepted and return 30 minutes", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  assert.deepEqual(actual, { overlaps: true, minutes: 30 });
});
